"""Read-only local connectivity checks. No schema initialization or data loading."""
import json
import subprocess
from pathlib import Path

import httpx
import psycopg
from dotenv import dotenv_values
from pymongo import MongoClient

ROOT = Path(__file__).resolve().parents[1]


class CheckFailure(RuntimeError):
    """Safe diagnostic generated by this verifier, without driver credentials."""


def verify():
    mounts = {'postgres': '/var/lib/postgresql/data', 'mongo': '/data/db',
              'neo4j': '/data', 'unopim': '/var/www/html/storage',
              'unopim-pgsql': '/var/lib/postgresql/data', 'unopim-redis': '/data',
              'unopim-elasticsearch': '/usr/share/elasticsearch/data'}
    required = ['postgres', 'mongo', 'neo4j', 'unopim', 'unopim-pgsql',
                'unopim-redis', 'unopim-elasticsearch', 'unopim-queue',
                'unopim-scheduler', 'unopim-mailpit']
    for service in required:
        cid = subprocess.check_output(
            ['docker', 'compose', '-f', 'docker-compose.yml', 'ps', '-q', service],
            cwd=ROOT, text=True).strip()
        if not cid:
            raise CheckFailure(f'{service}: container is not running')
        info = json.loads(subprocess.check_output(['docker', 'inspect', cid]))[0]
        health = info['State'].get('Health', {}).get('Status')
        if info['State']['Status'] != 'running' or health != 'healthy':
            raise CheckFailure(f'{service}: state={info["State"]["Status"]}, health={health}')
        if service in mounts:
            if not any(m['Type'] == 'volume' and m['Destination'] == mounts[service]
                       for m in info['Mounts']):
                raise CheckFailure(f'{service}: persistent data volume missing')
        print(f'{service}: running, healthy', flush=True)

    env = dotenv_values(ROOT / '.env')
    with psycopg.connect(host='127.0.0.1', dbname=env['POSTGRES_DB'],
                         user=env['POSTGRES_USER'], password=env['POSTGRES_PASSWORD'],
                         connect_timeout=5) as connection:
        assert connection.execute('SELECT 1').fetchone() == (1,)
    print('PostgreSQL authenticated query: PASS', flush=True)
    with MongoClient('127.0.0.1', username=env['MONGO_ROOT_USER'],
                     password=env['MONGO_ROOT_PASSWORD'], authSource='admin',
                     serverSelectionTimeoutMS=5000, socketTimeoutMS=5000) as mongo:
        assert mongo.admin.command('ping')['ok'] == 1
    print('MongoDB authenticated ping: PASS', flush=True)
    with httpx.Client(timeout=10, trust_env=False, follow_redirects=True) as client:
        response = client.post('http://127.0.0.1:7474/db/neo4j/tx/commit',
                               auth=('neo4j', env['NEO4J_PASSWORD']),
                               json={'statements': [{'statement': 'RETURN 1 AS ready'}]})
        response.raise_for_status()
        result = response.json()
        if result['errors'] or result['results'][0]['data'][0]['row'] != [1]:
            raise RuntimeError('Neo4j: authenticated query failed')
        print('Neo4j authenticated query: PASS', flush=True)
        for endpoint in ['/up', '/admin']:
            response = client.get('http://localhost:8000' + endpoint)
            response.raise_for_status()
            if response.status_code != 200:
                raise RuntimeError('UnoPim: HTTP readiness failed')
        print('UnoPim readiness and login page: PASS', flush=True)


if __name__ == '__main__':
    try:
        verify()
    except CheckFailure as error:
        print(f'FAIL: {error}')
        raise SystemExit(1)
    except Exception as error:
        # Do not print driver errors that could contain connection credentials.
        print(f'FAIL: infrastructure verification failed ({type(error).__name__}). '
              'Check container health, local ports and .env credentials.')
        raise SystemExit(1)
    print('PASS: local infrastructure health, storage and connectivity verified.')
